1	import {
2		type CanonicalLimits,
3		compareBytes,
4		decodeCanonical,
5		deepCloneCanonical,
6		encodeCanonical,
7		hashDomain,
8	} from "@ts-drp/canonical";
9	import { DRPError } from "@ts-drp/errors";
10	import {
11		applyPreparedBlueprintOperation,
12		type PreparedBlueprintRuntime,
13	} from "@ts-drp/protocol-v3/blueprint-application";
14	import type { IStagedStateMachine } from "@ts-drp/types";
15	
16	import { copyExactByteCarrier, copyTrustedBytes } from "./exact-byte-carrier.js";
17	import { topologicalOrder } from "./linearize.js";
18	import type { EpochVertex } from "./types.js";
19	
20	const APPLICATION_STATE_DOMAIN = "ts-drp/state/v3";
21	const APPLICATION_LIMITS: Readonly<CanonicalLimits> = Object.freeze({
22		maxBytes: 32_768,
23		maxDepth: 16,
24		maxItems: 16_384,
25	});
26	export interface BlueprintStateSnapshot {
27		readonly blueprintDigest: string;
28		readonly exactCanonicalStateBytes: Uint8Array;
29		readonly stateDigest: string;
30	}
31	
32	export interface BlueprintStateMachineInput {
33		readonly exactCanonicalInitialStateBytes: Uint8Array;
34		readonly expectedBlueprintDigest: string;
35		readonly expectedInitialStateDigest: string;
36		readonly preparedBlueprintRuntime: PreparedBlueprintRuntime;
37	}
38	
39	function hex(bytes: Uint8Array): string {
40		let output = "";
41		for (const byte of bytes) output += byte.toString(16).padStart(2, "0");
42		return output;
43	}
44	
45	function stateDigest(bytes: Uint8Array): string {
46		return hex(hashDomain(APPLICATION_STATE_DOMAIN, bytes));
47	}
48	
49	function applicationStateFailure(message: string, cause?: unknown): never {
50		throw new DRPError("INVALID_APPLICATION_STATE", message, cause === undefined ? undefined : { cause });
51	}
52	
53	function assertPreparedRuntimeProvenance(
54		expectedBlueprintDigest: string,
55		preparedBlueprintRuntime: PreparedBlueprintRuntime
56	): void {
57		try {
58			applyPreparedBlueprintOperation({
59				expectedBlueprintDigest,
60				operation: null,
61				preparedBlueprintRuntime,
62				state: null,
63			});
64		} catch (error) {
65			if (error instanceof DRPError && error.code === "BLUEPRINT_OPERATION_INVALID") return;
66			throw error;
67		}
68		throw new DRPError("BLUEPRINT_OPERATION_INVALID", "null unexpectedly matched a prepared blueprint operation");
69	}
70	
71	function applicationStateBytes(value: unknown): Uint8Array {
72		try {
73			const bytes = encodeCanonical(value, APPLICATION_LIMITS);
74			decodeCanonical(bytes, APPLICATION_LIMITS);
75			return bytes;
76		} catch (error) {
77			return applicationStateFailure("application value is outside the bounded canonical domain", error);
78		}
79	}
80	
81	function decodeInitialState(
82		input: Uint8Array,
83		expectedDigest: string
84	): { readonly bytes: Uint8Array; readonly value: unknown } {
85		let bytes: Uint8Array;
86		try {
87			bytes = copyExactByteCarrier(input, "initial application state");
88		} catch (error) {
89			return applicationStateFailure("initial application state bytes are unreadable", error);
90		}
91		if (!/^[0-9a-f]{64}$/u.test(expectedDigest) || stateDigest(bytes) !== expectedDigest) {
92			return applicationStateFailure("initial application state digest does not match exact bytes");
93		}
94		try {
95			const value = decodeCanonical(bytes, APPLICATION_LIMITS);
96			const reencoded = encodeCanonical(value, APPLICATION_LIMITS);
97			if (compareBytes(bytes, reencoded) !== 0) {
98				return applicationStateFailure("initial application state bytes are noncanonical");
99			}
100			return { bytes, value };
101		} catch (error) {
102			if (error instanceof DRPError) throw error;
103			return applicationStateFailure("initial application state bytes are invalid", error);
104		}
105	}
106	
107	/** A bounded v3 blueprint state machine with explicit fork/adopt semantics. */
108	export class BlueprintStateMachine implements IStagedStateMachine<BlueprintStateSnapshot, unknown, unknown> {
109		readonly #expectedBlueprintDigest: string;
110		readonly #preparedBlueprintRuntime: PreparedBlueprintRuntime;
111		#baseGeneration: object | undefined;
112		#exactCanonicalStateBytes: Uint8Array;
113		#generation: object = {};
114		#parent: BlueprintStateMachine | undefined;
115		#state: unknown;
116		#stateDigest: string;
117	
118		constructor(input: BlueprintStateMachineInput) {
