1	import { decodeCanonical, hashDomain } from "@ts-drp/canonical";
2	import type { DetachedClosureCandidate } from "@ts-drp/control-plane";
3	import { inspectCreatorTrustAdvance } from "@ts-drp/control-plane/creator-trust-advance";
4	import { inspectBoundedCreatorTrustAdvance } from "@ts-drp/control-plane/creator-trust-checkpoint-advance";
5	import type { CurrentAnchorTrust } from "@ts-drp/protocol-v3";
6	import {
7		CREATOR_AUTHOR_ISSUANCE_FRONTIERS_GENESIS_SENTINEL,
8		CREATOR_AUTHOR_ISSUANCE_FRONTIERS_KIND,
9		type CreatorAuthorIssuanceFrontiersIdentity,
10		openCreatorAuthorIssuanceFrontiers,
11		resolveCreatorAuthorIssuanceFrontiers,
12	} from "@ts-drp/protocol-v3/creator-author-issuance-frontiers";
13	import {
14		CREATOR_ISSUANCE_RETIREMENT_GENESIS_SENTINEL,
15		CREATOR_ISSUANCE_RETIREMENT_KIND,
16		type CreatorIssuanceRetirementIdentity,
17		openCreatorIssuanceRetirement,
18		resolveCreatorIssuanceRetirement,
19	} from "@ts-drp/protocol-v3/creator-issuance-retirement";
20	import { digestBlob, type GenerationRef } from "@ts-drp/storage";
21	
22	export interface CreatorTransitionClosure {
23		readonly candidates: readonly DetachedClosureCandidate[];
24		readonly closure: readonly GenerationRef[];
25	}
26	
27	export interface InspectCreatorTransitionAdvanceInput {
28		readonly current: CreatorTransitionClosure;
29		readonly currentTrust: CurrentAnchorTrust;
30		readonly mode: "stage" | "verify";
31		readonly proofRefs: readonly GenerationRef[];
32		readonly proposed: CreatorTransitionClosure;
33		readonly successorTrust: CurrentAnchorTrust;
34	}
35	
36	export type InspectCreatorTransitionAdvanceResult =
37		| Readonly<{ readonly ok: false; readonly reason: string }>
38		| Readonly<{
39				readonly kind: "successor";
40				readonly ok: true;
41				readonly proposed: CreatorTransitionClosure;
42		  }>;
43	
44	export interface VerifiedCreatorHistoricalIssuance {
45		readonly __verifiedCreatorHistoricalIssuance?: never;
46	}
47	
48	export interface CreatorHistoricalIssuanceIdentity {
49		readonly admittedAuthorSequence: number | null;
50		readonly author: string;
51		readonly closedAnchorDigest: string;
52		readonly closedEpoch: number;
53		readonly objectId: string;
54		readonly successorAnchorDigest: string;
55		readonly successorEpoch: number;
56	}
57	
58	const verifiedHistoricalIssuance = new WeakMap<VerifiedCreatorHistoricalIssuance, CreatorHistoricalIssuanceIdentity>();
59	
60	function record(candidate: DetachedClosureCandidate): Readonly<Record<string, unknown>> | undefined {
61		try {
62			const decoded = decodeCanonical(candidate.bytes);
63			return decoded !== null && typeof decoded === "object" && !Array.isArray(decoded)
64				? (decoded as Readonly<Record<string, unknown>>)
65				: undefined;
66		} catch {
67			return undefined;
68		}
69	}
70	
71	function compareRef(left: GenerationRef, right: GenerationRef): number {
72		return left.digest < right.digest ? -1 : left.digest > right.digest ? 1 : 0;
73	}
74	
75	function uniqueCandidate(
76		candidates: readonly DetachedClosureCandidate[],
77		kind: string,
78		epoch: number,
79		phase?: string
80	): DetachedClosureCandidate | undefined {
81		const matches = candidates.filter((candidate) => {
82			const decoded = record(candidate);
83			return (
84				decoded?.kind === kind &&
85				(decoded.kind === "drp-anchor-trust-state" ? decoded.currentEpoch : decoded.epoch) === epoch &&
86				(phase === undefined || decoded.phase === phase)
87			);
88		});
89		return matches.length === 1 ? matches[0] : undefined;
90	}
91	
92	function failure(reason: string): InspectCreatorTransitionAdvanceResult {
93		return Object.freeze({ ok: false as const, reason });
94	}
95	
96	function sameRef(left: GenerationRef, right: GenerationRef): boolean {
97		return left.byteLength === right.byteLength && left.digest === right.digest;
98	}
99	
100	function exactCandidate(candidate: DetachedClosureCandidate): boolean {
101		const digest = digestBlob(candidate.bytes);
102		return digest.ok && digest.value === candidate.ref.digest && candidate.bytes.byteLength === candidate.ref.byteLength;
103	}
104	
105	function hex(bytes: Uint8Array): string {
106		return Array.from(bytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
107	}
108	
109	function retirementCandidates(closure: CreatorTransitionClosure): readonly DetachedClosureCandidate[] {
110		return closure.candidates.filter((candidate) => record(candidate)?.kind === CREATOR_ISSUANCE_RETIREMENT_KIND);
111	}
