99		}
100		let admitted = input.priorAdmittedAuthorSequence;
101		let expected = firstExpected;
102		let truncated = false;
103		for (const row of rows) {
104			if (row.commit.authorSequence !== expected) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
