108			}
109			const bytes = row.commit.envelope.canonicalPreimageBytes;
110			const digest = hex(row.commit.envelope.digest);
111			const decoded = decodeCanonical(bytes);
112			if (
113				!plainRecord(decoded) ||
114				compareBytes(encodeCanonical(decoded), bytes) !== 0 ||
115				hex(hashDomain("ts-drp/vertex/v3", bytes)) !== digest ||
