117				decoded.author !== input.issuanceScope.author ||
118				decoded.epoch !== input.currentEpoch ||
119				decoded.objectId !== input.issuanceScope.objectId ||
120				decoded.authorSequence !== expected
121			) {
122				throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
123			}
124			const inGraph = input.graphVertexDigests.has(digest);
125			if (inGraph && truncated) throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
126			if (inGraph) admitted = expected;
127			else truncated = true;
128			expected += 1;
129		}
130		if (admitted === null || lineage.next <= admitted) {
131			throw new TypeError(CREATOR_ISSUANCE_RETIREMENT_UNAVAILABLE);
132		}
133		return Object.freeze({ admittedAuthorSequence: admitted, observedLineage: Object.freeze({ ...lineage }) });
