6357	async function readRebaseOutbox(registration: V3PlaneRegistration): Promise<V3RebaseOutboxResult> {
6358		if (!currentRegistration(registration)) {
6359			return ObjectFreeze({ detail: "v3 plane is not active", kind: "not-active" as const, ok: false as const });
6360		}
6361		if (registration.retainedBootstrapHold) {
6362			return ObjectFreeze({
6363				detail: "v3 retained bootstrap is incomplete",
6364				kind: "not-active" as const,
6365				ok: false as const,
6366			});
6367		}
6368		if (registration.rebaseSnapshot === undefined) {
6369			const crossSource =
6370				registration.displacedSource?.issuanceStore === undefined ? undefined : registration.displacedSource;
6371			const selectedStore = crossSource?.issuanceStore ?? registration.issuanceStore;
6372			const selectedScope = crossSource?.issuanceScope ?? registration.issuanceScope;
6373			const displaced: ClassifiedRebaseRow[] = [];
6374			let currentRecordCount = 0;
6375			let displacedRecordCount = 0;
6376			let afterKey: readonly [string, string, number] | undefined;
6377			beginHistoricalIssuanceScan(registration.historicalIssuance);
6378			for (;;) {
6379				let rawPage: unknown;
6380				try {
6381					rawPage = await selectedStore.readOutboxPage(
6382						afterKey === undefined ? { limit: 1, scope: selectedScope } : { afterKey, limit: 1, scope: selectedScope }
6383					);
6384				} catch {
6385					return ObjectFreeze({
6386						detail: "v3 rebase outbox read failed",
6387						kind: "store-failed" as const,
6388						ok: false as const,
6389					});
6390				}
6391				const page = onePage(rawPage);
6392				if (page === undefined) {
6393					return ObjectFreeze({
6394						detail: "v3 rebase outbox page is invalid",
6395						kind: "record-rejected" as const,
6396						ok: false as const,
6397					});
6398				}
6399				if (page === null) break;
6400				let classified: ClassifiedRebaseRow | undefined;
6401				try {
6402					classified = await authenticatedOutboxRow(registration, page, selectedStore, selectedScope);
6403				} catch {
6404					return ObjectFreeze({
6405						detail: "v3 rebase outbox record read failed",
6406						kind: "store-failed" as const,
6407						ok: false as const,
6408					});
6409				}
6410				if (classified === undefined || (afterKey !== undefined && classified.row.authorSequence <= afterKey[2])) {
6411					return ObjectFreeze({
6412						detail: "v3 rebase outbox record is invalid",
6413						kind: "record-rejected" as const,
6414						ok: false as const,
6415					});
6416				}
6417				afterKey = ObjectFreeze([selectedScope.objectId, selectedScope.author, classified.row.authorSequence] as const);
6418				const historical = classified.kind === "covered-historical" || classified.kind === "pinned-genesis";
6419				if (historical && !countHistoricalIssuanceRow(registration.historicalIssuance, classified.row.authorSequence)) {
6420					return ObjectFreeze({
6421						detail: "v3 rebase historical plane is at capacity",
6422						kind: "record-rejected" as const,
6423						ok: false as const,
6424					});
6425				}
6426				if (classified.kind === "current") {
6427					currentRecordCount += 1;
6428					if (currentRecordCount > registration.payload.parameters.maxEpochVertices) {
6429						return ObjectFreeze({
6430							detail: "v3 rebase current plane is at capacity",
6431							kind: "record-rejected" as const,
6432							ok: false as const,
6433						});
6434					}
6435					if (ReflectApply(SetPrototypeHas, registration.quarantinedDigests, [classified.authenticated.digest]) === true)
6436						continue;
6437				}
6438				if (!validRebaseRow(registration, classified)) {
6439					return ObjectFreeze({
6440						detail: "v3 rebase outbox record is invalid",
6441						kind: "record-rejected" as const,
6442						ok: false as const,
6443					});
6444				}
6445				if (classified.kind === "displaced" || historical) {
6446					if (historical && classified.row.publishState === "published") continue;
6447					if (crossSource === undefined && classified.row.publishState !== "pending") continue;
6448					const intents = rebaseIntents(
6449						historical ? registration.payload : (registration.displacedSource as V3DisplacedSourceAuthority).prepared,
6450						classified.authenticated
6451					);
6452					if (intents === undefined) {
6453						return ObjectFreeze({
6454							detail: "v3 rebase outbox intent is invalid",
6455							kind: "record-rejected" as const,
6456							ok: false as const,
6457						});
6458					}
6459					if (
